const out = [];
for (let i = 0; i < 10; i++) {
  if (window.__ensemble.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break;
  out.push(b.textContent.trim().slice(0, 30));
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
return 'clicked: ' + out.join(' > ');

const s = window.__ensemble.getState(); const chatId = s.chatId; const c = s.chats.find(x => x.id === chatId); const leadId = c.leadId || s.settings.leadId || s.accounts.find(a => a.enabled).id;
const st = window.__ensemble; const now = Date.now();
const goal = { id: 'g-swarm', text: 'Design the landing page, and keep going until the judges score it 45 of 50', doneWhen: 'both judging rounds score the winner 45 of 50 or more', status: 'active', round: 1, maxRounds: 6, check: 'fresh', createdAt: now - 60000, note: 'Round 1 winner scored 41 of 50: hierarchy and the pricing table are weakest.', log: [{ round: 0, ts: now - 30000, met: false, note: 'Round 1 winner scored 41 of 50: hierarchy and the pricing table are weakest.' }], mode: 'gocrazy' };
window.__goal = goal;
const put = () => st.setState(x => ({ chats: x.chats.map(k => k.id === chatId ? { ...k, goal: window.__goal } : k) }));
st.subscribe(x => { const k = x.chats.find(y => y.id === chatId); if (k && k.goal !== window.__goal) setTimeout(put, 0); });
put();
await window.ensemble.send({ chatId, to: leadId, text: '/gocrazy design the landing page' });
return 'swarm sent with a goal over it';
